function vi(c){return Math.min(c.variants.length-1,Math.max(0,state.viewed[c.id]||0))}function vr(c){return c.variants[vi(c)]}function ref(c,j){return `${c.id}.${String.fromCharCode(65+vi(c))}.${String(j+1).padStart(2,'0')}`}function text(c,j){return state.edits[ref(c,j)]?.trim()||vr(c).lines[j].text}function val(c,roles){const j=vr(c).lines.findIndex(l=>roles.some(r=>l.role.toLowerCase().includes(r)));return j<0?'':text(c,j)}
